package com.aistock.gateway.adminmarket;
import com.aistock.gateway.statistics.StatisticsIdentityClient;
import com.aistock.common.*;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.test.context.*;import org.springframework.test.annotation.DirtiesContext;import org.springframework.test.web.servlet.MockMvc;import jakarta.servlet.http.Cookie;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"spring.cloud.nacos.discovery.enabled=false","aistock.user.url=","aistock.prediction.url=","aistock.market.url=","aistock.scheduler.url=","SERVICE_TOKEN=test-only"}) @AutoConfigureMockMvc @DirtiesContext
class AdminMarketDiscoveryWiringTest {
 static AtomicInteger calls=new AtomicInteger();static final HttpServer SERVER=start();
 static HttpServer start(){try{var s=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);s.createContext("/api/v1/",x->{calls.incrementAndGet();var b="{\"code\":\"OK\",\"data\":{}}".getBytes(StandardCharsets.UTF_8);x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});s.start();return s;}catch(java.io.IOException e){throw new IllegalStateException(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){for(String service:List.of("user","prediction","market","scheduler"))r.add("spring.cloud.discovery.client.simple.instances.stock-"+service+"-service[0].uri",()->"http://127.0.0.1:"+SERVER.getAddress().getPort());}
 @Autowired MockMvc mvc;@MockBean StatisticsIdentityClient identity;
 @AfterAll static void stop(){SERVER.stop(0);}
 @Test void routesThreeReadsThroughDiscoveredNonDefaultPort()throws Exception{when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new StatisticsIdentityClient.Identity(UUID.randomUUID(),"ADMIN",1),"test"));for(String path:List.of(AdminMarketDataProxyTest.BASE,AdminMarketDataProxyTest.HISTORY,AdminMarketDataProxyTest.DETAIL))mvc.perform(get(path).cookie(new Cookie("AISTOCK_SESSION","admin"))).andExpect(status().isOk());assertEquals(3,calls.get());}
}
